1	import Stripe from "stripe";
2	
3	// ── Money-path safety rules for this file ──────────────────────────────────
4	// 1. Credit packs are a fixed server-side table, keyed by an opaque pack id.
5	//    A client can only ever say WHICH pack it wants — never an amount, a
6	//    price, or a credit count. This is the same class of bug that hit Nxeon's
7	//    hosting checkout (displayed price != charged price); the fix there was
8	//    "never trust a client-supplied number", and it applies here identically.
9	// 2. Credits are granted ONLY from the webhook, after Stripe confirms payment
10	//    — never from the client-side checkout-success redirect, which a user can
11	//    hit or forge without ever having paid.
12	// 3. Every webhook event is idempotency-guarded via StripeEvent (see schema)
13	//    — Stripe retries on any non-2xx, so this must be safe to receive twice.
14	
15	export type CreditPack = {
16	  id: string;
17	  credits: number;
18	  priceUsdCents: number;
19	  label: string;
20	};
21	
22	// Retail prices. Comment corrected 2026-08-22 — the previous version read
23	// "$1 = 500 credits list price ... packs get a modest discount at volume",
24	// which conflated COST with PRICE. Read literally it claimed the starter pack
25	// was a discount on $1 when it sells for $9, and anyone using it to reason
26	// about margin would have been badly wrong in both directions.
27	//
28	// What MICROS_PER_CREDIT fixes is the COST BASIS: 500 credits = $1.00 of
29	// underlying model spend (500 x 2000 micros). It is not a price anyone pays.
30	//
31	// Actual retail, with gross margin against that basis:
32	//   starter   500 credits   $9    $0.0180/credit   cost $1.00    88.9%
33	//   builder  2500 credits   $40   $0.0160/credit   cost $5.00    87.5%
34	//   pro      6000 credits   $90   $0.0150/credit   cost $12.00   86.7%
35	//
36	// The volume discount is real, but it is per-credit against the STARTER PACK
37	// (1.80c -> 1.60c -> 1.50c), not against the cost basis. Margin drifts down
38	// slightly as the discount deepens, which is the intended shape.
39	//
40	// Caveat: those margins hold only if the cost basis does. Measured builds have
41	// come in at 144 and 472 credits, so a $9 starter pack is somewhere between
42	// one and three builds. Do not publish a per-build price anywhere until
43	// scripts/eval has run a full sweep — see estimateCredits in lib/credits.ts.
44	export const CREDIT_PACKS: CreditPack[] = [
45	  { id: "starter", credits: 500, priceUsdCents: 900, label: "500 credits — $9" },
46	  { id: "builder", credits: 2500, priceUsdCents: 4000, label: "2,500 credits — $40" },
47	  { id: "pro", credits: 6000, priceUsdCents: 9000, label: "6,000 credits — $90" },
48	];
49	
50	export function getPack(packId: string): CreditPack | undefined {
51	  return CREDIT_PACKS.find((p) => p.id === packId);
52	}
53	
54	/** True once real Stripe keys are configured. Billing UI/routes degrade gracefully until then. */
55	export function billingEnabled(): boolean {
56	  return !!process.env.STRIPE_SECRET_KEY && !!process.env.STRIPE_WEBHOOK_SECRET;
57	}
58	
59	let client: Stripe | null = null;
60	
61	export function stripe(): Stripe {
62	  if (!process.env.STRIPE_SECRET_KEY) {
63	    throw new Error("Stripe is not configured (STRIPE_SECRET_KEY unset).");
64	  }
65	  if (!client) client = new Stripe(process.env.STRIPE_SECRET_KEY);
66	  return client;
67	}
