30	export async function GET(_req: Request, { params }: { params: Promise<{ id: string }> }) {
31	  const user = await requireUser().catch(() => null);
32	  if (!user) return Response.json({ error: "Not signed in." }, { status: 401 });
33	  const { id } = await params;
34	
35	  const project = await db.project.findFirst({
36	    where: { id, userId: user.id },
37	    include: {
38	      // Source is what the agent/Code-view work with; the compiled build
39	      // output isn't meant to be shown or edited directly.
40	      files: { where: { published: false, kind: "source" } },
41	      messages: { orderBy: { createdAt: "asc" } },
42	    },
43	  });
