66	
67	  if (project.files.length === 0) {
68	    return Response.json({ error: "Nothing to publish yet — generate a site first." }, { status: 400 });
69	  }
70	
71	  // Only gate genuinely new subdomains — republishing an already-live project
72	  // isn't the spam-farming vector this protects against.
73	  if (!project.publishedAt) {
74	    const rateLimit = await checkPublishRateLimit(user.id);
75	    if (!rateLimit.allowed) {
76	      return Response.json(
77	        { error: "You've published a lot of new sites today — try again tomorrow." },
78	        { status: 429, headers: { "Retry-After": String(rateLimit.retryAfterSeconds) } },
79	      );
80	    }
81	  }
82	
83	  // Scan both the compiled output (what's actually served) and the source
84	  // (a comment or string that got stripped by the build can still leak if
85	  // someone reads it another way) — belt and suspenders, cheap either way.
86	  const sourceFiles = await db.projectFile.findMany({
87	    where: { projectId: id, published: false, kind: "source" },
88	  });
89	  const publishable = [...project.files, ...sourceFiles].map((f) => ({
90	    path: f.path,
91	    content: f.content,
92	  }));
93	
94	  const leaks = scanForSecrets(publishable);
95	  if (leaks.length > 0) {
96	    const { path, kind } = leaks[0];
97	    return Response.json(
98	      { error: `Publishing blocked: found what looks like a real secret in ${path} (${kind}). Remove it and try again.` },
99	      { status: 400 },
100	    );
101	  }
102	
103	  // Abuse check. Same last-gate position as the secret scan, for the same
104	  // reason: after this line the files are reachable at *.kodely.site by anyone,
105	  // and a phishing clone hosted there is Kodely's abuse report to answer.
106	  //
107	  // moderateForPublish returns SIGNALS, not a verdict (see lib/moderation.ts) —
108	  // policy is applied right here, and only `high` refuses. Everything below
109	  // `high` is expected to be mostly benign (an integration logo, a mock login
110	  // UI) and must not stand between a legitimate user and their own site.
111	  const moderation = await moderateForPublish(publishable);
112	  const blockers = blockingFindings(moderation);
113	
114	  // Record BEFORE the policy branch, so the blocked path cannot return without
115	  // its rows: a refused publish leaves no other trace anywhere: no published
116	  // files, no event, nothing on the project. These rows are the only evidence
117	  // it happened.
118	  //
119	  // Awaited, not fire-and-forget like track() above — the full argument is on
120	  // recordModerationFindings() in lib/moderation.ts. The short version: this is
121	  // a moderation record about one identifiable site, not an aggregate metric,
122	  // a floating promise is not guaranteed to complete once we return a Response,
123	  // and the call cannot throw or change the outcome either way. Whatever this
124	  // line does, the publish below behaves exactly as it did before it existed.
125	  await recordModerationFindings({ projectId: id, result: moderation, blocked: blockers });
126	
127	  if (blockers.length > 0) {
128	    const worst = blockers[0];
129	    console.warn(
130	      `[kodely] publish blocked by moderation project=${id} user=${user.id} provider=${moderation.provider}`,
131	      blockers.map((f) => ({ rule: f.rule, path: f.path, evidence: f.evidence })),
132	    );
133	    return Response.json(
134	      {
135	        error: `Publishing blocked: ${worst.note} (${worst.path} — "${worst.evidence}"). If this is a mistake, edit the page or reply here and we'll take a look.`,
136	        moderation: { rule: worst.rule, path: worst.path },
137	      },
138	      { status: 400 },
139	    );
140	  }
141	  if (moderation.findings.length > 0) {
142	    // ModerationFinding is now the durable record; this stays as an operational
143	    // breadcrumb and is the one place that still shows EVERY occurrence. The
144	    // table records a non-blocking finding once per distinct (rule, file,
145	    // snippet) and skips exact repeats on republish — see the volume note in
146	    // lib/moderation.ts — so "fired again on an unchanged page" is a log
147	    // question, not a query.
148	    console.warn(
149	      `[kodely] publish moderation signals project=${id} user=${user.id} provider=${moderation.provider}`,
150	      moderation.findings.map((f) => ({ rule: f.rule, severity: f.severity, path: f.path })),
151	    );
152	  }
153	
154	  await db.$transaction([
155	    db.projectFile.deleteMany({ where: { projectId: id, published: true, kind: "build" } }),
156	    db.projectFile.createMany({
157	      data: project.files.map((f) => ({
158	        projectId: id,
159	        path: f.path,
160	        content: f.content,
161	        published: true,
162	        kind: "build",
163	      })),
164	    }),
165	    db.project.update({ where: { id }, data: { publishedAt: new Date() } }),
166	  ]);
167	
168	  // The North Star. `firstPublish` separates "reached the promise for the
169	  // first time" from a routine republish — the funnel counts the former.
170	  track(EVENTS.sitePublished, {
171	    userId: user.id,
172	    props: {
173	      projectId: id,
174	      slug: project.slug,
175	      firstPublish: !project.publishedAt,
176	      files: project.files.length,
177	    },
178	  });
179	
180	  const host = req.headers.get("host") ?? "";
181	  const url = host.includes("staging")
182	    ? `https://${host}/api/site/${project.slug}`
183	    : `https://${project.slug}.${SITES_BASE}`;
184	
185	  return Response.json({ url });
186	}
