1	import { Prisma } from "@prisma/client";
2	import { db } from "@/lib/db";
3	import { requireUser } from "@/lib/auth";
4	
5	export const dynamic = "force-dynamic";
6	
7	// The checkpoint list — every successful build is a restore point. Deliberately
8	// excludes filesSnapshot from the list payload (could be large across many
9	// builds); the restore route reads it directly by id instead.
10	export async function GET(_req: Request, { params }: { params: Promise<{ id: string }> }) {
11	  const user = await requireUser().catch(() => null);
12	  if (!user) return Response.json({ error: "Not signed in." }, { status: 401 });
13	  const { id } = await params;
14	
15	  const project = await db.project.findFirst({ where: { id, userId: user.id } });
16	  if (!project) return Response.json({ error: "Project not found." }, { status: 404 });
17	
18	  const builds = await db.build.findMany({
19	    where: {
20	      projectId: id,
21	      status: "SUCCEEDED",
22	      // A checkpoint is only real if its snapshot still exists. The retention
23	      // job (lib/retention.ts) clears filesSnapshot on old builds to reclaim
24	      // storage — ~105 kB per build — and without this filter those rows kept
25	      // rendering as restore points that 404 with "Checkpoint not found." when
26	      // clicked. A restore point that cannot restore is worse than no entry.
27	      filesSnapshot: { not: Prisma.DbNull },
28	    },
29	    orderBy: { createdAt: "desc" },
30	    // Bounded. This was unlimited, so a heavily-iterated project returned every
31	    // checkpoint it had ever produced on every panel open.
32	    take: 100,
33	    select: { id: true, prompt: true, createdAt: true, filesWritten: true },
34	  });
35	
36	  return Response.json({ builds });
37	}
