1	"use client";
2	
3	import type { RefObject } from "react";
4	
5	// The preview pane, plus the width switcher and the click-to-select toggle
6	// above it.
7	//
8	// Generated sites are prompted to hold up down to 380px, and until now there
9	// was no way to check that without publishing and opening the result on a
10	// phone. So: three widths, a real pixel number next to them, and nothing else.
11	// No rounded phone shell, no notch, no rotate button — a device chrome would
12	// imply we are emulating a device, and we are not. We are changing a width.
13	//
14	// The iframe is fed a SELF-CONTAINED document through `srcdoc` rather than
15	// pointed at a URL. See the long note at the top of preview-agent.ts for why:
16	// in short, every subresource request made from inside this frame is treated
17	// as cross-site and arrives without the session cookie, so a preview built out
18	// of separate asset requests cannot load at all. Inlining is what makes the
19	// preview render, and it is also what gives us somewhere to put the selection
20	// agent. The `sandbox` attribute below is UNCHANGED and must stay that way —
21	// adding `allow-same-origin` would hand generated customer code the parent
22	// origin.
23	//
24	// The iframe element is deliberately NOT re-keyed when the width changes, so
25	// switching widths resizes the live page rather than reloading it. That is the
26	// difference between testing a responsive layout and testing a page load.
27	
28	export type DeviceId = "desktop" | "tablet" | "mobile";
29	
30	export const DEVICES: { id: DeviceId; label: string; width: number | null; note: string }[] = [
31	  { id: "desktop", label: "Desktop", width: null, note: "full width" },
32	  { id: "tablet", label: "Tablet", width: 768, note: "768px" },
33	  // 380 rather than a real handset width: it is the floor the site generator
34	  // is told to support, so it is the number worth testing against.
35	  { id: "mobile", label: "Mobile", width: 380, note: "380px" },
36	];
37	
38	const FOCUS_RING =
39	  "focus-visible:outline-none focus-visible:ring-2 focus-visible:ring-black/40 dark:focus-visible:ring-white/40";
40	
41	export default function PreviewFrame({
42	  doc,
43	  loading,
44	  error,
45	  reloadKey,
46	  device,
47	  onDeviceChange,
48	  frameRef,
49	  selectMode,
50	  selectAvailable,
51	  onToggleSelectMode,
52	}: {
53	  /** The assembled document, or null before the first load finishes. */
54	  doc: string | null;
55	  loading: boolean;
56	  error: string | null;
57	  reloadKey: number;
58	  device: DeviceId;
59	  onDeviceChange: (device: DeviceId) => void;
60	  frameRef: RefObject<HTMLIFrameElement | null>;
61	  selectMode: boolean;
62	  /** The preview answered the handshake, so the toggle can do something. */
63	  selectAvailable: boolean;
64	  onToggleSelectMode: () => void;
65	}) {
66	  const active = DEVICES.find((d) => d.id === device) ?? DEVICES[0];
67	
68	  return (
69	    <div className="flex h-full flex-col">
70	      <div className="flex flex-wrap items-center justify-between gap-2 border-b border-black/10 px-3 py-2 dark:border-white/10">
71	        <div className="flex flex-wrap items-center gap-2">
72	          <div
73	            role="group"
74	            aria-label="Preview width"
75	            className="flex items-center gap-1 rounded-lg border border-black/10 p-0.5 text-xs dark:border-white/10"
76	          >
77	            {DEVICES.map((d) => (
78	              <button
79	                key={d.id}
80	                type="button"
81	                onClick={() => onDeviceChange(d.id)}
82	                aria-pressed={device === d.id}
83	                className={`rounded-md px-2 py-1 ${FOCUS_RING} ${
84	                  device === d.id
85	                    ? "bg-black text-white dark:bg-white dark:text-black"
86	                    : "text-black/60 hover:text-black dark:text-white/60 dark:hover:text-white"
87	                }`}
88	              >
89	                {d.label}
90	              </button>
91	            ))}
92	          </div>
93	
94	          {/* Disabled until the preview has actually answered. A toggle that
95	              looks live but cannot target anything is worse than no toggle. */}
96	          <button
97	            type="button"
98	            onClick={onToggleSelectMode}
99	            aria-pressed={selectMode}
100	            disabled={!selectAvailable}
101	            title={
102	              selectAvailable
103	                ? "Click an element in the preview to refer to it in your next change"
104	                : "Available once the preview has loaded"
105	            }
106	            className={`rounded-lg border px-2 py-1 text-xs disabled:opacity-40 ${FOCUS_RING} ${
107	              selectMode
108	                ? "border-black bg-black text-white dark:border-white dark:bg-white dark:text-black"
109	                : "border-black/10 text-black/60 hover:text-black dark:border-white/10 dark:text-white/60 dark:hover:text-white"
110	            }`}
111	          >
112	            Select element
113	          </button>
114	        </div>
115	
116	        {/* The number matters more than the label — "Mobile" is a guess,
117	            "380px" is a fact you can compare a bug report against. */}
118	        <span className="text-xs text-black/40 dark:text-white/40">
119	          Preview at {active.note}
120	        </span>
121	      </div>
122	
123	      {/* Constrained widths keep their real pixel size and let this container
124	          scroll if the pane is narrower — clamping them to the pane would
125	          make the "768px" label a lie, which is the one thing this control
126	          cannot afford. The scroll is contained here, never on the page. */}
127	      <div className="flex min-h-0 flex-1 justify-center overflow-auto">
128	        {error ? (
129	          <p className="m-auto max-w-sm px-6 text-center text-sm text-black/60 dark:text-white/60">
130	            {error}
131	          </p>
132	        ) : doc === null ? (
133	          <p className="m-auto px-6 text-sm text-black/45 dark:text-white/45">
134	            {loading ? "Loading preview…" : "Nothing to preview yet."}
135	          </p>
136	        ) : (
137	          <iframe
138	            key={reloadKey}
139	            ref={frameRef}
140	            srcDoc={doc}
141	            sandbox="allow-scripts allow-forms"
142	            title={`Live preview at ${active.note}`}
143	            style={active.width ? { width: active.width } : undefined}
144	            className={`h-full shrink-0 bg-white ${
145	              active.width
146	                ? "border-x border-black/10 dark:border-white/10"
147	                : "w-full border-0"
148	            }`}
149	          />
150	        )}
151	      </div>
152	    </div>
153	  );
154	}
