8	const APP_URL = process.env.APP_URL ?? "https://kodely.me";
9	
10	export async function POST(req: Request) {
11	  if (!billingEnabled()) {
12	    return Response.json({ error: "Billing isn't set up yet." }, { status: 503 });
13	  }
14	
15	  const user = await requireUser().catch(() => null);
16	  if (!user) return Response.json({ error: "Not signed in." }, { status: 401 });
17	
18	  const body = (await req.json().catch(() => null)) as { packId?: string } | null;
19	  // The ONLY thing the client controls is which pack it wants. Credits and
20	  // price are always resolved server-side from CREDIT_PACKS — see lib/stripe.ts.
21	  const pack = getPack(body?.packId ?? "");
22	  if (!pack) return Response.json({ error: "Unknown credit pack." }, { status: 400 });
23	
24	  const client = stripe();
25	
26	  let customerId = user.stripeCustomerId;
27	  if (!customerId) {
28	    const customer = await client.customers.create({
29	      email: user.email,
30	      metadata: { kodelyUserId: user.id },
31	    });
32	    customerId = customer.id;
33	    await db.user.update({ where: { id: user.id }, data: { stripeCustomerId: customerId } });
34	  }
35	
36	  const session = await client.checkout.sessions.create({
37	    mode: "payment",
38	    customer: customerId,
39	    // The webhook is the only place credits are ever granted — this metadata
40	    // is what tells it how much to grant and to whom.
41	    metadata: { kodelyUserId: user.id, packId: pack.id, credits: String(pack.credits) },
42	    line_items: [
43	      {
44	        price_data: {
45	          currency: "usd",
46	          unit_amount: pack.priceUsdCents,
47	          product_data: { name: `Kodely — ${pack.label}` },
48	        },
49	        quantity: 1,
50	      },
51	    ],
52	    success_url: `${APP_URL}/dashboard?topup=success`,
53	    cancel_url: `${APP_URL}/dashboard?topup=cancelled`,
54	  });
55	
56	  // Started, not completed. Paired with credits.purchased in the webhook, this
57	  // is what makes checkout abandonment visible — the gap between the two is
58	  // the number that matters.
59	  track(EVENTS.checkoutStarted, {
60	    userId: user.id,
61	    props: { packId: pack.id, credits: pack.credits, priceUsdCents: pack.priceUsdCents },
62	  });
63	
64	  return Response.json({ url: session.url });
65	}
