1	import { db } from "@/lib/db";
2	import { billingEnabled, getPack, stripe } from "@/lib/stripe";
3	import { grantCredits } from "@/lib/credits";
4	import { track, EVENTS } from "@/lib/events";
5	import type Stripe from "stripe";
6	
7	export const dynamic = "force-dynamic";
8	
9	// The ONLY place credits are ever granted for a purchase. Never trust the
10	// client-side success redirect — a user can hit that URL without paying.
11	// Every event is idempotency-guarded via StripeEvent so a Stripe retry
12	// (fires on any non-2xx response) can never double-grant credits.
13	export async function POST(req: Request) {
14	  if (!billingEnabled()) return new Response("Billing not configured.", { status: 503 });
15	
16	  const signature = req.headers.get("stripe-signature");
17	  if (!signature) return new Response("Missing signature.", { status: 400 });
18	
19	  const rawBody = await req.text();
20	  let event: Stripe.Event;
21	  try {
22	    event = stripe().webhooks.constructEvent(
23	      rawBody,
24	      signature,
25	      process.env.STRIPE_WEBHOOK_SECRET!,
26	    );
27	  } catch (err) {
28	    console.error("[kodely] stripe webhook signature verification failed", err);
29	    return new Response("Invalid signature.", { status: 400 });
30	  }
31	
32	  // Claim the event FIRST, before granting anything. `id` is unique, so a
33	  // concurrent or retried delivery hits a P2002 conflict here and we skip —
34	  // this is the actual dedupe mutex. Claiming before granting (not after)
35	  // matters: if we crash between grant and claim, a retry would grant twice.
36	  try {
37	    await db.stripeEvent.create({ data: { id: event.id, type: event.type } });
38	  } catch (err) {
39	    const code = (err as { code?: string })?.code;
40	    if (code === "P2002") return Response.json({ ok: true, deduped: true });
41	    throw err;
42	  }
43	
44	  if (event.type === "checkout.session.completed") {
45	    const session = event.data.object as Stripe.Checkout.Session;
46	    if (session.payment_status === "paid") {
47	      const userId = session.metadata?.kodelyUserId;
48	      const packId = session.metadata?.packId;
49	      const pack = packId ? getPack(packId) : undefined;
50	
51	      // Re-derive the credit amount from the fixed pack table rather than
52	      // trusting the metadata's echoed `credits` string — metadata is
53	      // attacker-writable in principle if the integration ever changes.
54	      if (userId && pack) {
55	        await grantCredits(userId, pack.credits, `stripe:${session.id}`);
56	        // Fires only after the grant lands, so the event can never claim a
57	        // purchase the ledger doesn't show. The StripeEvent idempotency guard
58	        // above means a webhook retry won't double-count this either.
59	        track(EVENTS.creditsPurchased, {
60	          userId,
61	          props: { packId: pack.id, credits: pack.credits, priceUsdCents: pack.priceUsdCents },
62	        });
63	      } else {
64	        console.error("[kodely] stripe webhook: missing/invalid metadata", session.id);
65	      }
66	    }
67	  }
68	
69	  return Response.json({ ok: true });
70	}
