1	import { requireUser } from "@/lib/auth";
2	import {
3	  ASSET_KINDS,
4	  assetCatalogSummary,
5	  findAssets,
6	  getAsset,
7	  type AssetKind,
8	} from "@/lib/assets";
9	
10	export const dynamic = "force-dynamic";
11	
12	const MAX_QUERY_CHARS = 120;
13	
14	/**
15	 * The asset library over HTTP, for a future asset-picker UI in the editor.
16	 *
17	 *   GET /api/assets                  -> catalogue summary (what's in here)
18	 *   GET /api/assets?q=coffee         -> matches across every kind
19	 *   GET /api/assets?q=phone&kind=icon&limit=12
20	 *   GET /api/assets?kind=gradient    -> browse one kind
21	 *   GET /api/assets?id=icon:phone    -> one asset by its stable id
22	 *
23	 * Auth-gated the same way as app/api/projects/route.ts. There is nothing
24	 * secret in here — the data is static and hand-authored — but it is our
25	 * content, the payload is large enough to be worth not serving anonymously,
26	 * and every other route under app/api that isn't auth/health/webhook is gated.
27	 * Nothing here reads or writes the database or costs credits.
28	 */
29	export async function GET(req: Request) {
30	  const user = await requireUser().catch(() => null);
31	  if (!user) return Response.json({ error: "Not signed in." }, { status: 401 });
32	
33	  const url = new URL(req.url);
34	  const id = url.searchParams.get("id")?.trim();
35	  const q = url.searchParams.get("q")?.trim() ?? "";
36	  const kindParam = url.searchParams.get("kind")?.trim().toLowerCase();
37	  const limitParam = url.searchParams.get("limit");
38	  const weightParam = url.searchParams.get("weight")?.trim().toLowerCase();
39	
40	  if (q.length > MAX_QUERY_CHARS) {
41	    return Response.json({ error: "Search term is too long." }, { status: 400 });
42	  }
43	
44	  // A comma list lets the picker ask for, say, "gradient,mesh" in one call.
45	  let kind: AssetKind[] | undefined;
46	  if (kindParam) {
47	    const requested = kindParam.split(",").map((k) => k.trim());
48	    const unknown = requested.filter((k) => !ASSET_KINDS.includes(k as AssetKind));
49	    if (unknown.length > 0) {
50	      return Response.json(
51	        { error: `Unknown kind: ${unknown.join(", ")}. Valid kinds: ${ASSET_KINDS.join(", ")}.` },
52	        { status: 400 },
53	      );
54	    }
55	    kind = requested as AssetKind[];
56	  }
57	
58	  const weight = weightParam === "light" || weightParam === "bold" ? weightParam : "regular";
59	
60	  const parsedLimit = limitParam === null ? NaN : Number(limitParam);
61	  const limit = Number.isFinite(parsedLimit) ? Math.min(Math.max(Math.trunc(parsedLimit), 1), 100) : 24;
62	
63	  if (id) {
64	    const asset = getAsset(id, { weight });
65	    if (!asset) return Response.json({ error: `No asset with id "${id}".` }, { status: 404 });
66	    return Response.json({ asset });
67	  }
68	
69	  // No query and no kind filter: describe the catalogue rather than dumping
70	  // several hundred rendered assets at a picker that only wanted to know what
71	  // exists.
72	  if (!q && !kind) {
73	    return Response.json({ summary: assetCatalogSummary(), kinds: ASSET_KINDS });
74	  }
75	
76	  const assets = findAssets(q, { kind, limit, weight });
77	  return Response.json({ query: q, kind: kind ?? null, count: assets.length, assets });
78	}
